SELECT 
FROM public.modifier_zones
WHERE game_id = #{gameId}

    AND (
        strpos(lower(modifier_zone_key), lower(#{keyword})) > 0
        OR strpos(lower(name), lower(#{keyword})) > 0
    )


    AND domain = #{domain}


    AND status = #{status}

ORDER BY sort_order ASC, name ASC, modifier_zone_key ASC

SELECT 
FROM public.modifier_zones
WHERE game_id = #{gameId} AND modifier_zone_key = #{modifierZoneKey}

SELECT COUNT(1)
FROM public.modifier_zones
WHERE game_id = #{gameId} AND modifier_zone_key = #{modifierZoneKey}

SELECT COUNT(1)
FROM public.skill_effect_attribute_change_details
WHERE game_id = #{gameId} AND modifier_zone_key = #{modifierZoneKey}

SELECT COUNT(1)
FROM public.skill_effect_damage_modifier_details
WHERE game_id = #{gameId} AND modifier_zone_key = #{modifierZoneKey}

SELECT COUNT(1)
FROM public.skill_effect_healing_modifier_details
WHERE game_id = #{gameId} AND modifier_zone_key = #{modifierZoneKey}

